#include <algorithm>
#include <fstream>
#include <iostream>
#include <queue>
#include <stack>
#include <sstream>
#include <string>
#include <unordered_map>
#include <vector>
using namespace std;
struct Student{int id=0,semester=1,year=0;string name,dept,email;};
struct Course{int id=0,semester=1,capacity=0;string name,dept;vector<int> enrolled;};
struct Book{int id=0,total=0,available=0;string title,author,category;};
struct Loan{int id=0,student=0,book=0;string issue,due,returnedDate="-";bool returned=false;};
struct Result{int student=0,course=0;double marks=0;string grade;};
class Campus {
 vector<Student> students; vector<Course> courses; vector<Book> books; vector<Loan> loans; vector<Result> results;
 unordered_map<int,size_t> si,ci,bi; queue<pair<int,int>> waiting; stack<string> actions;
 int ns=1001,nc=501,nb=201,nl=1;
 static string grade(double m){if(m>=90)return "O";if(m>=80)return "A+";if(m>=70)return "A";if(m>=60)return "B";if(m>=50)return "C";if(m>=40)return "D";return "F";}
 static string safe(string s){for(char&c:s)if(c=='|'||c=='\n'||c=='\r')c=' ';return s;}
 void indexes(){si.clear();ci.clear();bi.clear();for(size_t i=0;i<students.size();i++)si[students[i].id]=i;for(size_t i=0;i<courses.size();i++)ci[courses[i].id]=i;for(size_t i=0;i<books.size();i++)bi[books[i].id]=i;}
 static bool num(const string&s,int&v){try{size_t n;v=stoi(s,&n);return n==s.size();}catch(...){return false;}}
 public:
 static int ask(const string&p,int lo,int hi){string s;int v;for(;;){cout<<p;getline(cin,s);if(num(s,v)&&v>=lo&&v<=hi)return v;cout<<"Invalid value; enter "<<lo<<".."<<hi<<".\n";}}
 static string date(const string&p){string s;for(;;){cout<<p;getline(cin,s);if(s.size()==10&&s[4]=='-'&&s[7]=='-')return s;cout<<"Use YYYY-MM-DD.\n";}}
 void load(){string line;ifstream f("data/students.txt");while(getline(f,line)){stringstream s(line);Student x;string a,b,c,d,e;if(getline(s,a,'|')&&getline(s,x.name,'|')&&getline(s,x.dept,'|')&&getline(s,b,'|')&&getline(s,x.email,'|')&&getline(s,c)){try{x.id=stoi(a);x.semester=stoi(b);x.year=stoi(c);if(x.id>0&&!si.count(x.id)){students.push_back(x);ns=max(ns,x.id+1);si[x.id]=students.size()-1;}}catch(...){}}}
 f.close();ifstream g("data/courses.txt");while(getline(g,line)){stringstream s(line);Course x;string a,b,c,d,e,ids;if(getline(s,a,'|')&&getline(s,x.name,'|')&&getline(s,x.dept,'|')&&getline(s,b,'|')&&getline(s,c,'|')&&getline(s,ids)){try{x.id=stoi(a);x.semester=stoi(b);x.capacity=stoi(c);stringstream q(ids);string id;while(getline(q,id,','))if(!id.empty())x.enrolled.push_back(stoi(id));if(x.id>0&&!ci.count(x.id)){courses.push_back(x);nc=max(nc,x.id+1);ci[x.id]=courses.size()-1;}}catch(...){}}}
 f.close();ifstream h("data/books.txt");while(getline(h,line)){stringstream s(line);Book x;string a,b,c,d,e;if(getline(s,a,'|')&&getline(s,x.title,'|')&&getline(s,x.author,'|')&&getline(s,x.category,'|')&&getline(s,b,'|')&&getline(s,c)){try{x.id=stoi(a);x.total=stoi(b);x.available=stoi(c);if(x.id>0&&!bi.count(x.id)){books.push_back(x);nb=max(nb,x.id+1);bi[x.id]=books.size()-1;}}catch(...){}}}
 f.close();ifstream k("data/loans.txt");while(getline(k,line)){stringstream s(line);Loan x;string a,b,c,d,e,r,t;if(getline(s,a,'|')&&getline(s,b,'|')&&getline(s,c,'|')&&getline(s,x.issue,'|')&&getline(s,x.due,'|')&&getline(s,x.returnedDate,'|')&&getline(s,r)){try{x.id=stoi(a);x.student=stoi(b);x.book=stoi(c);x.returned=r=="1";loans.push_back(x);nl=max(nl,x.id+1);}catch(...){}}}
 f.close();ifstream m("data/results.txt");while(getline(m,line)){stringstream s(line);Result x;string a,b,c;if(getline(s,a,'|')&&getline(s,b,'|')&&getline(s,c,'|')&&getline(s,x.grade)){try{x.student=stoi(a);x.course=stoi(b);x.marks=stod(c);results.push_back(x);}catch(...){}}}indexes();}
 bool saveStudents(){ofstream f("data/students.txt");for(auto&x:students)f<<x.id<<'|'<<safe(x.name)<<'|'<<safe(x.dept)<<'|'<<x.semester<<'|'<<safe(x.email)<<'|'<<x.year<<'\n';return f.good();}
 bool saveCourses(){ofstream f("data/courses.txt");for(auto&x:courses){f<<x.id<<'|'<<safe(x.name)<<'|'<<safe(x.dept)<<'|'<<x.semester<<'|'<<x.capacity<<'|';for(size_t i=0;i<x.enrolled.size();i++){if(i)f<<',';f<<x.enrolled[i];}f<<'\n';}return f.good();}
 bool saveBooks(){ofstream f("data/books.txt");for(auto&x:books)f<<x.id<<'|'<<safe(x.title)<<'|'<<safe(x.author)<<'|'<<safe(x.category)<<'|'<<x.total<<'|'<<x.available<<'\n';return f.good();}
 bool saveLoans(){ofstream f("data/loans.txt");for(auto&x:loans)f<<x.id<<'|'<<x.student<<'|'<<x.book<<'|'<<x.issue<<'|'<<x.due<<'|'<<x.returnedDate<<'|'<<x.returned<<'\n';return f.good();}
 bool saveResults(){ofstream f("data/results.txt");for(auto&x:results)f<<x.student<<'|'<<x.course<<'|'<<x.marks<<'|'<<x.grade<<'\n';return f.good();}
public:
 Campus(){load();}
 bool save(){return saveStudents()&&saveCourses()&&saveBooks()&&saveLoans()&&saveResults();}
 void studentMenu(){cout<<"1 Register 2 List 3 Search ID 4 Update 5 Remove\n";int c=ask("Choice: ",1,5);if(c==1){Student x;cout<<"Name: ";getline(cin,x.name);if(x.name.empty()){cout<<"Name required.\n";return;}cout<<"Department: ";getline(cin,x.dept);x.semester=ask("Semester 1-8: ",1,8);cout<<"Email: ";getline(cin,x.email);x.year=ask("Enrollment year 2000-2100: ",2000,2100);x.id=ns++;students.push_back(x);indexes();actions.push("Registered student "+to_string(x.id));cout<<"Registered ID "<<x.id<<"\n";saveStudents();}else if(c==2){if(students.empty())cout<<"No students.\n";for(auto&x:students)cout<<x.id<<" | "<<x.name<<" | "<<x.dept<<" | semester "<<x.semester<<" | "<<x.email<<" | "<<x.year<<"\n";}else if(c==3){int id=ask("ID: ",1,9999999);if(!si.count(id))cout<<"Not found.\n";else{auto&x=students[si[id]];cout<<x.id<<" | "<<x.name<<" | "<<x.dept<<" | "<<x.email<<"\n";}}else if(c==4){int id=ask("ID: ",1,9999999);if(!si.count(id)){cout<<"Not found.\n";return;}auto&x=students[si[id]];string s;cout<<"Name ["<<x.name<<"]: ";getline(cin,s);if(!s.empty())x.name=s;cout<<"Department ["<<x.dept<<"]: ";getline(cin,s);if(!s.empty())x.dept=s;x.semester=ask("Semester 1-8: ",1,8);cout<<"Email ["<<x.email<<"]: ";getline(cin,s);if(!s.empty())x.email=s;saveStudents();cout<<"Updated.\n";}else{int id=ask("ID remove: ",1,9999999);if(!si.count(id)){cout<<"Not found.\n";return;}for(auto&c:courses)if(find(c.enrolled.begin(),c.enrolled.end(),id)!=c.enrolled.end()){cout<<"Remove enrollments before student.\n";return;}for(auto&l:loans)if(l.student==id&&!l.returned){cout<<"Active loan prevents removal.\n";return;}students.erase(students.begin()+si[id]);results.erase(remove_if(results.begin(),results.end(),[&](Result&r){return r.student==id;}),results.end());indexes();saveStudents();saveResults();cout<<"Removed.\n";}}
 void courseMenu(){cout<<"1 Create 2 List 3 Enroll 4 Remove enrollment 5 Enrollment report\n";int c=ask("Choice: ",1,5);if(c==1){Course x;cout<<"Course name: ";getline(cin,x.name);if(x.name.empty()){cout<<"Name required.\n";return;}cout<<"Department: ";getline(cin,x.dept);x.semester=ask("Semester 1-8: ",1,8);x.capacity=ask("Capacity: ",1,500);x.id=nc++;courses.push_back(x);indexes();saveCourses();cout<<"Course ID "<<x.id<<" created.\n";}else if(c==2){for(auto&x:courses)cout<<x.id<<" | "<<x.name<<" | "<<x.dept<<" | "<<x.enrolled.size()<<"/"<<x.capacity<<"\n";}else if(c==3){int sid=ask("Student ID: ",1,9999999),id=ask("Course ID: ",1,9999999);if(!si.count(sid)||!ci.count(id)){cout<<"Unknown student/course.\n";return;}auto&v=courses[ci[id]].enrolled;if(find(v.begin(),v.end(),sid)!=v.end()){cout<<"Duplicate enrollment denied.\n";return;}if((int)v.size()>=courses[ci[id]].capacity){cout<<"Capacity full.\n";return;}v.push_back(sid);saveCourses();cout<<"Enrolled.\n";}else if(c==4){int sid=ask("Student ID: ",1,9999999),id=ask("Course ID: ",1,9999999);if(!ci.count(id)){cout<<"Course missing.\n";return;}auto&v=courses[ci[id]].enrolled;auto it=find(v.begin(),v.end(),sid);if(it==v.end()){cout<<"Enrollment missing.\n";return;}v.erase(it);results.erase(remove_if(results.begin(),results.end(),[&](Result&r){return r.student==sid&&r.course==id;}),results.end());saveCourses();saveResults();cout<<"Enrollment removed.\n";}else{for(auto&x:courses){cout<<x.name<<" enrolled="<<x.enrolled.size()<<"\n";for(int id:x.enrolled)if(si.count(id))cout<<"  "<<id<<" "<<students[si[id]].name<<"\n";}}}
 void resultsMenu(){cout<<"1 Enter marks 2 Marksheet 3 Rank\n";int c=ask("Choice: ",1,3);if(c==1){int sid=ask("Student ID: ",1,9999999),cid=ask("Course ID: ",1,9999999);if(!si.count(sid)||!ci.count(cid)||find(courses[ci[cid]].enrolled.begin(),courses[ci[cid]].enrolled.end(),sid)==courses[ci[cid]].enrolled.end()){cout<<"Student must be enrolled in valid course.\n";return;}string s;cout<<"Marks 0-100: ";getline(cin,s);double m;try{size_t n;m=stod(s,&n);if(n!=s.size()||m<0||m>100)throw 1;}catch(...){cout<<"Invalid marks.\n";return;}auto it=find_if(results.begin(),results.end(),[&](Result&r){return r.student==sid&&r.course==cid;});Result r{sid,cid,m,grade(m)};if(it==results.end())results.push_back(r);else *it=r;saveResults();cout<<"Recorded grade "<<r.grade<<".\n";}else if(c==2){int id=ask("Student ID: ",1,9999999);if(!si.count(id)){cout<<"Student missing.\n";return;}cout<<"Marksheet: "<<students[si[id]].name<<"\n";bool found=false;for(auto&r:results)if(r.student==id){cout<<"Course "<<r.course<<" marks "<<r.marks<<" grade "<<r.grade<<"\n";found=true;}if(!found)cout<<"No results.\n";}else{priority_queue<pair<double,pair<int,int>>> pq;for(auto&r:results)pq.push({r.marks,{r.student,r.course}});if(pq.empty())cout<<"No results.\n";while(!pq.empty()){auto x=pq.top();pq.pop();cout<<x.second.first<<" course "<<x.second.second<<" marks "<<x.first<<"\n";}}}
 void libraryMenu(){cout<<"1 Add book 2 Catalog 3 Issue 4 Return 5 Loan report\n";int c=ask("Choice: ",1,5);if(c==1){Book x;cout<<"Title: ";getline(cin,x.title);if(x.title.empty()){cout<<"Required.\n";return;}cout<<"Author: ";getline(cin,x.author);cout<<"Category: ";getline(cin,x.category);x.total=ask("Copies 1-1000: ",1,1000);x.available=x.total;x.id=nb++;books.push_back(x);indexes();saveBooks();cout<<"Book ID "<<x.id<<" added.\n";}else if(c==2){for(auto&x:books)cout<<x.id<<" | "<<x.title<<" | "<<x.author<<" | available "<<x.available<<"/"<<x.total<<"\n";}else if(c==3){int sid=ask("Student ID: ",1,9999999),id=ask("Book ID: ",1,9999999);if(!si.count(sid)||!bi.count(id)){cout<<"Unknown ID.\n";return;}auto&b=books[bi[id]];if(b.available==0){waiting.push({sid,id});cout<<"Unavailable; placed in session waiting queue.\n";return;}for(auto&l:loans)if(!l.returned&&l.student==sid&&l.book==id){cout<<"Already on active loan.\n";return;}Loan l;l.id=nl++;l.student=sid;l.book=id;l.issue=date("Issue date: ");l.due=date("Due date: ");loans.push_back(l);b.available--;saveLoans();saveBooks();actions.push("Issued book "+to_string(id));cout<<"Issued loan ID "<<l.id<<".\n";}else if(c==4){int id=ask("Loan ID: ",1,9999999);auto it=find_if(loans.begin(),loans.end(),[&](Loan&l){return l.id==id;});if(it==loans.end()||it->returned){cout<<"Active loan not found.\n";return;}it->returnedDate=date("Return date: ");it->returned=true;if(bi.count(it->book))books[bi[it->book]].available++;saveLoans();saveBooks();cout<<"Returned.\n";}else{if(loans.empty())cout<<"No loans.\n";for(auto&l:loans)cout<<"Loan "<<l.id<<" student "<<l.student<<" book "<<l.book<<" issue "<<l.issue<<" due "<<l.due<<" return "<<l.returnedDate<<" "<<(l.returned?"returned":"active")<<"\n";}}
 void reports(){cout<<"1 Overdue loans 2 Course enrollments\n";int c=ask("Choice: ",1,2);if(c==1){string today=date("Today's date: ");bool f=false;for(auto&l:loans)if(!l.returned&&l.due<today){cout<<"Overdue loan "<<l.id<<" student "<<l.student<<" book "<<l.book<<" due "<<l.due<<"\n";f=true;}if(!f)cout<<"No overdue loans.\n";}else for(auto&x:courses)cout<<x.id<<" "<<x.name<<" enrollment count="<<x.enrolled.size()<<"\n";}
 static void mergeNames(vector<Student>&v,int l,int m,int r){vector<Student>tmp;int i=l,j=m+1;while(i<=m&&j<=r){if(v[i].name<=v[j].name)tmp.push_back(v[i++]);else tmp.push_back(v[j++]);}while(i<=m)tmp.push_back(v[i++]);while(j<=r)tmp.push_back(v[j++]);for(size_t k=0;k<tmp.size();++k)v[l+(int)k]=tmp[k];}
 static void mergeSortNames(vector<Student>&v,int l,int r){if(l>=r)return;int m=l+(r-l)/2;mergeSortNames(v,l,m);mergeSortNames(v,m+1,r);mergeNames(v,l,m,r);}
 void sortSearch(){cout<<"1 Merge Sort students by name 2 Sort by ID 3 Binary Search by ID\n";int c=ask("Choice: ",1,3);if(c==1){if(students.size()>1)mergeSortNames(students,0,(int)students.size()-1);indexes();cout<<"Sorted by name using Merge Sort.\n";}else{sort(students.begin(),students.end(),[](const Student&a,const Student&b){return a.id<b.id;});indexes();if(c==2)cout<<"Sorted by ID.\n";else{int id=ask("Search ID: ",1,9999999);int lo=0,hi=(int)students.size()-1,found=-1;while(lo<=hi){int mid=lo+(hi-lo)/2;if(students[mid].id==id){found=mid;break;}if(students[mid].id<id)lo=mid+1;else hi=mid-1;}if(found<0)cout<<"Not found.\n";else cout<<"Found "<<students[found].name<<"\n";}}}
 void recent(){if(actions.empty())cout<<"No recent action this session.\n";else cout<<actions.top()<<"\n";}
};
int main(){Campus app;bool run=true;while(run){cout<<"\n===== CAMPUS MANAGEMENT SYSTEM =====\n1 Student Management\n2 Course & Enrollment\n3 Academic Results\n4 Library Management\n5 Reports\n6 Sorting & Search DSA\n7 Recent Action (Stack)\n8 Save All\n9 Exit\n";int c=Campus::ask("Module: ",1,9);switch(c){case 1:app.studentMenu();break;case 2:app.courseMenu();break;case 3:app.resultsMenu();break;case 4:app.libraryMenu();break;case 5:app.reports();break;case 6:app.sortSearch();break;case 7:app.recent();break;case 8:cout<<(app.save()?"Saved.\n":"Save error.\n");break;case 9:cout<<(app.save()?"Saved.\n":"Save warning.\n");cout<<"Goodbye.\n";run=false;break;}}}
